; 1Ch bytes (1B4B..1D0A), 64 terrain records of 8 bytes (1D0B..1F0A), palettes
; 1F0B..1F6A (packed rows 1F0B (8) and 1F13 (10), RGB rows 1F23 (18) and 1F3B
; (30)). Template +0A, +0C, +19 and terrain +6 are never read by this
; executable: in the shipped files they hold sizes/offsets for another plane
; layout (+0A = +08 = w*h/2, +0C = w*h/4, +19 = animation base +15 * 4/5,
; terrain +6 = third-plane offset). The read request is 1000h bytes, so an
; overlong file would overwrite DS 1B4B..2B4A including callback word 25A0 and
; the floater pair table; short reads keep old bytes. Startup clears this once;
; the level reset 4551 stops at 0FC9. Special setup overlays the palette halves.
