;   read-mask cache 6748 (8D66 only): all h rows are built first at stride w+1 (BP = copy end),
;   ANDed with VGA plane 3, then reread forward from 6748 (8E18) for every plane.
; SHR/RCR/INC always walk forward from the base whatever DF is. All decoded callers that
