; rows by 6767 and the cache, h*(w+1) <= 2000h, by 8747. Pinned assets stay lower (terrain
; source rows <= 6720, object caches <= 6828). The spacing 6748-6706 = 42h and A948-6748 =
; 4200h = 100h rows * 42h is consistent with declared 66-byte rows and a 256-row cache.
; Behavior to keep: DF1 source rows overwrite 6705/6704 (the live destination advance) for
; w >= 1/2 before it is reread; DF1 cache rows step downward from 6748 toward 4748; DF0
; source w >= 42h reaches the mask base; w = 0 makes the RCR loop run 65536 times over every
; DS offset (including SS:0000.. through DS:A950), w = FFh wraps the output count to 65536,
